/**
 * The Terrain tab: a world generated by `procedural-terrains` and exported into the level.
 *
 * The package is a runtime, not a studio: it ships a viewer that owns its own renderer, camera and
 * orbit controls, a configuration model (seed, layout, height scale, noise), a document format and
 * an exporter. That is exactly the shape an editor tab needs — the tab owns the recipe, the viewer
 * draws it, and the export produces a GLB that becomes an ordinary model asset in this project.
 *
 * Nothing here reaches into the viewer's scene: the only things crossing the boundary are the
 * configuration going in and the exported bytes coming out, which is why the tab can load the
 * package lazily and keep the editor's own renderer untouched.
 */

// The numbers are the package's own defaults (`layout 8 × 128`, `noiseScale` in the twenties, a
// 560-unit height), because its validator owns the accepted ranges: a value outside one is refused
// by name rather than quietly clamped, so the tab starts from something it will definitely accept.
const DEFAULTS = { name: 'Terrain', seed: 1337, chunkCount: 8, chunkSize: 128, heightScale: 560,
  octaves: 7, scale: 26, meshRes: 256, seaLevel: 0, exportCollision: true, exportWater: false,
  // `null` means "the runtime's own classic stack"; a project that has been edited through the
  // layer panel stores the stack itself, so the same world comes back and can be edited again.
  stack: null };

export function defaultTerrain() { return { ...DEFAULTS }; }
export function terrainRecipe(project) { return { ...DEFAULTS, ...(project?.terrain || {}) }; }

/** The `configuration` patch the viewer takes, from the recipe the project stores. */
export function terrainConfiguration(recipe) {
  return {
    heightScale: recipe.heightScale,
    seaLevel: recipe.seaLevel,
    layout: { chunkCount: recipe.chunkCount, chunkSize: recipe.chunkSize },
    source: { kind: 'noise', seed: recipe.seed, octaves: recipe.octaves, scale: recipe.scale,
      ...(recipe.stack?.layers?.length ? { stack: recipe.stack } : {}) },
  };
}

/**
 * The GLB out of an export result.
 *
 * `exportTerrain` answers with a map of file name to bytes — mesh, heightmap, collision, splat,
 * preset — so the mesh is picked by extension rather than by position, and a missing mesh is an
 * error worth naming instead of a silent nothing.
 */
export function meshFromExport(files = {}) {
  const name = Object.keys(files).find(file => /\.glb$/i.test(file)) ||
    Object.keys(files).find(file => /\.obj$/i.test(file));
  if (!name) throw new Error('The terrain export contained no mesh file');
  return { name, bytes: files[name], binary: /\.glb$/i.test(name) };
}

export function createTerrainPanel({ root, project: getProject, edit, status, addModel }) {
  const body = document.createElement('div');
  body.className = 'terrain-body';
  const form = document.createElement('form');
  form.className = 'terrain-form';
  const stage = document.createElement('div');
  stage.className = 'terrain-stage';
  const placeholder = document.createElement('p');
  placeholder.className = 'muted';
  placeholder.textContent = 'Open this tab to build a terrain. Generating one asks the package for its '
    + 'viewer and draws it here; Export to level turns it into a model asset placed in the map.';
  stage.append(placeholder);
  body.append(form, stage);
  root.replaceChildren(body);

  let viewer = null, loading = null, modules = null;
  let recipe = terrainRecipe(getProject());

  const field = (label, key, { min, max, step = 1 } = {}) => {
    const row = document.createElement('label');
    row.className = 'terrain-field';
    const name = document.createElement('span');
    name.textContent = label;
    const input = document.createElement('input');
    input.type = 'number'; input.id = `terrain-${key}`;
    input.value = String(recipe[key]);
    if (min !== undefined) input.min = String(min);
    if (max !== undefined) input.max = String(max);
    input.step = String(step);
    input.addEventListener('change', () => {
      const value = Number(input.value);
      if (!Number.isFinite(value)) { input.value = String(recipe[key]); return; }
      recipe = { ...recipe, [key]: value };
      save();
    });
    row.append(name, input);
    return row;
  };

  const toolbar = document.createElement('div');
  toolbar.className = 'terrain-actions';
  const generate = document.createElement('button');
  generate.type = 'button'; generate.id = 'terrain-generate'; generate.textContent = 'Generate';
  const exportLevel = document.createElement('button');
  exportLevel.type = 'button'; exportLevel.id = 'terrain-export-level'; exportLevel.textContent = 'Export to level';
  const reset = document.createElement('button');
  reset.type = 'button'; reset.id = 'terrain-reset'; reset.textContent = 'Reset';
  const state = document.createElement('p');
  state.id = 'terrain-status';
  state.setAttribute('role', 'status');
  toolbar.append(generate, exportLevel, reset);

  const title = document.createElement('h2');
  title.textContent = 'Terrain';
  const hint = document.createElement('p');
  hint.className = 'muted';
  hint.textContent = 'A generated world, exported as a model asset. The recipe is saved with the '
    + 'project, so reopening the tab rebuilds the same terrain and the same export.';
  form.append(title, hint,
    field('Seed', 'seed', { min: -2147483648, max: 2147483647 }),
    field('Chunks per side', 'chunkCount', { min: 1, max: 64 }),
    field('Chunk size', 'chunkSize', { min: 8, max: 4096 }),
    field('Height scale', 'heightScale', { min: 0, max: 100000, step: 8 }),
    field('Noise octaves', 'octaves', { min: 1, max: 16 }),
    field('Noise scale', 'scale', { min: .01, max: 1000, step: .1 }),
    field('Mesh resolution', 'meshRes', { min: 16, max: 1024, step: 16 }),
    toolbar, state);

  // The layer stack is the real recipe; the fields above are its quick controls. It is built lazily
  // with the rest of the tab, because it imports the runtime's schema module.
  const layersHost = document.createElement('div');
  layersHost.className = 'terrain-stack';
  layersHost.id = 'terrain-stack';
  form.append(layersHost);
  let stackEditor = null;
  void import('./terrain-layers.js').then(({ createStackEditor }) => {
    stackEditor = createStackEditor({
      root: layersHost,
      status,
      onChange: stack => {
        recipe = { ...recipe, stack };
        syncNoiseFields();
        save();
        // Regenerating on every edit is what makes the panel an editor rather than a form: the
        // viewer is rebuilt from the new stack, which is the only honest answer to "what does this
        // look like".
        scheduleRebuild();
      },
    });
    if (recipe.stack?.layers?.length) stackEditor.set(recipe.stack);
  }).catch(error => {
    layersHost.textContent = `The noise layer editor could not load: ${error.message}`;
  });

  function save() {
    edit(next => { next.terrain = { ...recipe }; }, 'Terrain recipe saved');
  }

  /**
   * Whether the two noise fields above still decide anything.
   *
   * With no stack the runtime builds its classic single layer from these two numbers, so they are
   * the recipe. Once a stack exists, the stack *is* the shape and those numbers are ignored — showing
   * them would be a control that does nothing, which is worse than a control that is absent.
   */
  function syncNoiseFields() {
    const stacked = Boolean(recipe.stack?.layers?.length);
    for (const key of ['octaves', 'scale']) {
      const input = root.querySelector(`#terrain-${key}`);
      if (input?.parentElement) input.parentElement.hidden = stacked;
    }
  }

  async function loadModules() {
    if (modules) return modules;
    loading ||= Promise.all([import('procedural-terrains/viewer'), import('procedural-terrains/export')])
      .then(([viewerModule, exportModule]) => (modules = { viewer: viewerModule, exporter: exportModule }));
    return loading;
  }

  let rebuildTimer = 0;
  function scheduleRebuild() {
    clearTimeout(rebuildTimer);
    rebuildTimer = setTimeout(() => void build(), 320);
  }

  async function build() {
    generate.disabled = true;
    state.textContent = 'Generating…';
    try {
      const { viewer: viewerModule } = await loadModules();
      viewer?.dispose?.();
      viewer = null;
      stage.replaceChildren();
      viewer = await viewerModule.createTerrainViewer(stage, { configuration: terrainConfiguration(recipe) });
      state.textContent = `Terrain ${recipe.seed} ready: ${recipe.chunkCount} × ${recipe.chunkCount} chunks of ${recipe.chunkSize}.`;
      root.dataset.terrainReady = 'true';
    } catch (error) {
      // A GPU-less session is the usual reason: the tab says so instead of showing an empty box.
      stage.replaceChildren();
      stage.append(placeholder);
      placeholder.textContent = `The terrain viewer could not start: ${error.message}`;
      state.textContent = '';
      status(`Terrain viewer: ${error.message}`, true);
      root.dataset.terrainReady = 'false';
    } finally { generate.disabled = false; }
  }

  async function exportToLevel() {
    if (!viewer) { status('Generate a terrain first', true); return; }
    exportLevel.disabled = true;
    state.textContent = 'Exporting…';
    try {
      const { exporter } = await loadModules();
      const result = await exporter.exportTerrain(viewer.terrain, {
        format: 'glb', meshRes: recipe.meshRes, includeMesh: true, includeSkirts: true,
        exportCollision: recipe.exportCollision, exportWater: recipe.exportWater,
        onProgress: message => { state.textContent = String(message || 'Exporting…'); },
      });
      const mesh = meshFromExport(result.files);
      const placed = await addModel({ bytes: mesh.bytes, binary: mesh.binary, name: `Terrain ${recipe.seed}` });
      state.textContent = placed
        ? `Exported ${(mesh.bytes.length / 1048576).toFixed(1)} MB and placed ${placed} in the level.`
        : 'The export produced no mesh.';
      status(state.textContent, !placed);
    } catch (error) {
      state.textContent = '';
      status(`Terrain export failed: ${error.message}`, true);
    } finally { exportLevel.disabled = false; }
  }

  generate.addEventListener('click', () => void build());
  reset.addEventListener('click', () => {
    recipe = defaultTerrain();
    for (const [key, value] of Object.entries(recipe)) {
      const input = root.querySelector(`#terrain-${key}`);
      if (input) input.value = String(value ?? '');
    }
    stackEditor?.set(null);
    syncNoiseFields();
    save();
    void build();
  });
  exportLevel.addEventListener('click', () => void exportToLevel());

  function render() {
    recipe = terrainRecipe(getProject());
    for (const [key, value] of Object.entries(recipe)) {
      const input = root.querySelector(`#terrain-${key}`);
      if (input) input.value = String(value);
    }
    stackEditor?.set(recipe.stack);
    syncNoiseFields();
    // The viewer is built on demand: a project with no terrain yet should not pay for a WebGL2
    // context or the package's workers until the author asks for one.
    if (!viewer && !loading) void build();
  }

  return { render, dispose() { viewer?.dispose?.(); viewer = null; } };
}
